#include <iostream>
using namespace std;

int main() {
    int scores[3] = {70, 85, 90};
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += scores[i];
    }
    double average = total / 3.0;
    cout << "Average: " << average << endl;
    if (average >= 75) {
        cout << "Level completed!" << endl;
    } else {
        cout << "Try again!" << endl;
    }
    return 0;
}

